import http from 'node:http';
import {readFileSync} from 'node:fs';
const catalogo=JSON.parse(readFileSync('src/lib/catalogo-base.json','utf8'));

let filas;let pagoSimulado=null;let correos=[];
function reset(){filas={pedidos_manuales:[{id:'00000000-0000-4000-8000-000000000001',referencia_numero:42,estado:'pagado',estado_entrega:'pendiente_preparar',metodo:'sinpe',total_productos:500,costo_envio:0,total_cobrar:500,comprobante_path:null,correo_cliente_en:'2026-10-13',correo_pago_en:'2026-10-13',creado_en:'2026-10-13T12:00:00Z',cliente:{nombre:'Retiro',apellidos:'QA',modalidad:'retiro',correo:'cliente@example.test',telefono:'+50688883333',direccion:'Dirección de prueba',provincia:'Alajuela',canton:'Atenas',distrito:'Atenas',receptor:'Persona autorizada QA',telefonoReceptor:'88884444',tipoIdentificacion:'fisica',identificacion:'123456789',factura:'electronica',razonSocial:'Empresa QA',actividad:'Actividad QA',correoFactura:'factura@example.test',direccionFiscal:'Dirección fiscal QA',notas:'Llamar antes de entregar'},articulos:[{nombre:'Producto QA',cantidad:1}]}],pedidos_tilopay:[{id:'00000000-0000-4000-8000-000000000002',referencia_numero:43,estado:'pagado',estado_entrega:'pendiente_preparar',entorno:'produccion',total:500,creado_en:'2026-10-13T12:00:00Z',cliente:{nombre:'Envío',apellidos:'QA',modalidad:'envio'},articulos:[]},{id:'00000000-0000-4000-8000-000000000003',referencia_numero:44,estado:'rechazado',resultado_tilopay:'Fondos insuficientes',estado_entrega:'pendiente_preparar',entorno:'produccion',total:500,creado_en:'2026-10-13T12:00:00Z',cliente:{nombre:'Rechazado',apellidos:'QA'},articulos:[]}]};}reset();
http.createServer(async(req,res)=>{res.setHeader('Content-Type','application/json');const url=new URL(req.url,'http://127.0.0.1:3135');if(url.pathname==='/tilopay/login')return res.end(JSON.stringify({access_token:'fixture-only'}));if(url.pathname==='/tilopay/processPayment'){let raw='';for await(const chunk of req)raw+=chunk;pagoSimulado=JSON.parse(raw);return res.end(JSON.stringify({type:'100',url:'https://secure.tilopay.com/qa-sin-cobro'}));}if(url.pathname==='/pago-simulado')return res.end(JSON.stringify(pagoSimulado));if(url.pathname==='/brevo'){let raw='';for await(const c of req)raw+=c;correos.push(JSON.parse(raw));return res.end(JSON.stringify({messageId:'fixture-only'}));}if(url.pathname==='/correos')return res.end(JSON.stringify(correos));if(url.pathname==='/health')return res.end('{}');if(url.pathname==='/reset'){reset();correos=[];if(url.searchParams.has('plazo')){filas.pedidos_manuales[0].estado=url.searchParams.has('revision')?'revision':'pendiente_pago';filas.pedidos_manuales[0].cliente.idioma=url.searchParams.get('idioma')??'es';if(url.searchParams.get('plazo')==='nuevo')Object.assign(filas.pedidos_manuales[0].cliente,{plazo_entrega_dias_habiles:7,plazo_entrega_desde:'pago_confirmado'});}if(url.searchParams.has('archivos')){filas.pedidos_manuales[0].estado_entrega='entregado';}if(url.searchParams.has('pendiente')){Object.assign(filas.pedidos_tilopay[1],{estado:'pendiente',creado_en:new Date().toISOString(),cliente:{nombre:'Luis',apellidos:'QA',telefono:'88883333',idioma:url.searchParams.get('idioma')??'es',modalidad:'retiro'}});}if(url.searchParams.has('express')){filas.pedidos_manuales[0].cliente.modalidad='express';filas.pedidos_manuales[0].cliente.nombre='Express SINPE';filas.pedidos_manuales[0].estado_entrega='preparando';filas.pedidos_tilopay[0].cliente={nombre:'Express tarjeta 1',apellidos:'QA',modalidad:'express'};filas.pedidos_tilopay[0].estado_entrega='preparando';filas.pedidos_tilopay.push({...filas.pedidos_tilopay[0],id:'00000000-0000-4000-8000-000000000004',referencia_numero:45,cliente:{nombre:'Express tarjeta 2',apellidos:'QA',modalidad:'express'}});}return res.end('{}');}
 if(url.pathname==='/rest/v1/catalogo_privado')return res.end(JSON.stringify({contenido:catalogo}));
 const tabla=url.pathname.split('/').at(-1),rows=filas[tabla];if(!rows)return res.end('[]');
 if(req.method==='POST'){let raw='';for await(const chunk of req)raw+=chunk;const nuevo={...JSON.parse(raw),referencia_numero:100+rows.length,creado_en:new Date().toISOString(),estado_entrega:'pendiente_preparar'};rows.push(nuevo);return res.end(JSON.stringify(nuevo));}

 const matches=rows.filter(row=>{const a=url.searchParams.get('archivado_en');if(a==='is.null'&&row.archivado_en)return false;if(a==='not.is.null'&&!row.archivado_en)return false;if(a?.startsWith('eq.')&&a!=='eq.'+row.archivado_en)return false;return ['id','estado','estado_entrega'].every(k=>!url.searchParams.get(k)||url.searchParams.get(k)==='eq.'+row[k]);});
 if(req.method==='PATCH'){let raw='';for await(const chunk of req)raw+=chunk;const cambios=JSON.parse(raw);for(const row of matches)Object.assign(row,cambios);}
 const single=req.headers.accept?.includes('vnd.pgrst.object');return res.end(JSON.stringify(single?matches[0]??null:matches));
}).listen(3135,'127.0.0.1');
